const ISSUES = [
  "Delivery delayed / ETA wrong", "Missing or wrong items",
  "Food cold, spilled or poorly packed", "Refund not received or rejected",
  "Customer support unhelpful", "High platform / delivery fee or surge",
  "Membership issue (Swiggy One / Zomato Gold)", "Delivery partner behaviour",
  "Order cancelled after payment", "Coupon or offer not applied",
  "App bug (payment failure, crash, login/OTP)", "Restaurant food quality",
  "Cash on delivery unavailable", "Service not available in area",
  "Location / GPS issue", "Language support request",
  "Too many ads or notifications", "Scam or unexplained charge",
  "Cancellation fee charged (customer cancelled)",
  "Menu prices higher than restaurant", "Offers or discounts reduced",
];

const SYSTEM = `You analyze Indian food-delivery app reviews (Swiggy, Zomato).
Reviews may be in English, Hindi or Hinglish.
Known issue labels: ${JSON.stringify(ISSUES)}

Return a JSON object: {"results": [ ...one object per review... ]}
Each object: {"n": <same n>, "text_en": "<English translation>",
 "service": "food"|"instamart"|"dineout"|"other", "is_complaint": true|false,
 "issues": [{"label": "...", "category": "bug|ux|pricing|delivery|support|restaurant_quality|feature_request",
             "severity": 1-5, "is_new": false}]}

Rules:
- Reuse a known label EXACTLY as written whenever the meaning matches.
- Only create a new label (is_new: true) for a genuinely different problem; under 8 words.
- A review can have several issues. Praise-only reviews get "issues": [].
- Complaints about a restaurant's cooking use "Restaurant food quality".
- Severity: 1 = minor annoyance, 5 = lost money or could not use the app.
- Never create vague labels like "general dissatisfaction" or "poor service".
- "Order cancelled after payment" is ONLY when the platform or restaurant cancelled.
  If the customer cancelled and was charged, use "Cancellation fee charged (customer cancelled)".
- Use "Scam or unexplained charge" ONLY when no specific cause is given.
- A concrete suggestion is a feature request: short label, category "feature_request", never "none".
Return ONLY the JSON object.`;

const batch = $input.all().map((it, i) => ({
  n: i, id: it.json.id, text: String(it.json.text).slice(0, 800),
}));

return [{
  json: {
    ids: batch.map(x => x.id),
    body: {
      model: "openai/gpt-oss-120b",
      messages: [
        { role: "system", content: SYSTEM },
        { role: "user", content: JSON.stringify(batch.map(({ n, text }) => ({ n, text }))) },
      ],
      response_format: { type: "json_object" },
      temperature: 0,
    },
  },
}];

const ids = $('Build request').first().json.ids;
const reviews = [];
const issues = [];

try {
  const content = $input.first().json.choices[0].message.content;
  for (const r of JSON.parse(content).results) {
    const id = ids[r.n];
    if (!id) continue;
    reviews.push({ id, service: r.service, text_en: r.text_en });
    for (const iss of (r.issues || [])) {
      issues.push({ review_id: id, label: iss.label, category: iss.category,
                    severity: iss.severity, is_new: !!iss.is_new });
    }
  }
} catch (e) {
  // bad batch: reviews stay analyzed=false and are retried next run
}

return [{ json: { reviews, issues } }];
